package za.co.lepetse.admin;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
@RestController
@RequestMapping("/api/admin/supply/suppliers")
public class AdminSupplierDirectory {
 private final JdbcTemplate db;
 private final com.fasterxml.jackson.databind.ObjectMapper json;
 public AdminSupplierDirectory(JdbcTemplate db,com.fasterxml.jackson.databind.ObjectMapper json){this.db=db;this.json=json;}
 public record Profile(@NotBlank @Size(max=200) String name,@NotNull @Size(max=200) String contactName,@NotNull @Email @Size(max=254) String email,@NotNull @Size(max=100) String phone,@NotNull @Size(max=2000) String address,@NotNull @Size(max=2000) String paymentTerms,@NotNull @Size(max=2000) String deliveryNotes,@Size(max=100) String codNumber,@Size(max=200) String salesPerson,@Size(max=200) String bankName,@Size(max=250) String accountName,@Size(max=100) String accountNumber,@Size(max=200) String branchName,@Size(max=50) String branchCode,@Size(max=50) String electronicBranchCode){}
 @GetMapping List<Map<String,Object>> list(){return db.queryForList("select s.*,(select count(distinct l.supplier_sku) from supplier_quote_line l join supplier_quote q on q.id=l.quote_id where q.supplier_id=s.id) item_count,(select max(q.quote_date) from supplier_quote q where q.supplier_id=s.id) last_price_date from supplier s order by lower(s.name),s.id");}
 @GetMapping("/{id}") Map<String,Object> detail(@PathVariable long id){var rows=db.queryForList("select * from supplier where id=?",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Supplier not found.");return rows.getFirst();}
 private void unique(String name,Long id){if(db.queryForObject("select count(*) from supplier where lower(name)=lower(?) and (?::bigint is null or id<>?)",Integer.class,name.trim(),id,id)>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"A supplier with this name already exists.");}
 @PostMapping @Transactional Map<String,Object> create(@Valid @RequestBody Profile p){unique(p.name(),null);long id=db.queryForObject("insert into supplier(name,contact_name,email,phone,address,payment_terms,delivery_notes,cod_number,sales_person,bank_name,account_name,account_number,branch_name,branch_code,electronic_branch_code) values (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) returning id",Long.class,p.name().trim(),p.contactName().trim(),p.email().trim(),p.phone().trim(),p.address().trim(),p.paymentTerms().trim(),p.deliveryNotes().trim(),Objects.toString(p.codNumber()," ").trim(),Objects.toString(p.salesPerson()," ").trim(),Objects.toString(p.bankName()," ").trim(),Objects.toString(p.accountName()," ").trim(),Objects.toString(p.accountNumber()," ").trim(),Objects.toString(p.branchName()," ").trim(),Objects.toString(p.branchCode()," ").trim(),Objects.toString(p.electronicBranchCode()," ").trim());return Map.of("id",id);}
 @PutMapping("/{id}") @Transactional Map<String,Object> update(@PathVariable long id,@Valid @RequestBody Profile p){detail(id);unique(p.name(),id);db.update("update supplier set name=?,contact_name=?,email=?,phone=?,address=?,payment_terms=?,delivery_notes=?,cod_number=coalesce(?,cod_number),sales_person=coalesce(?,sales_person),bank_name=coalesce(?,bank_name),account_name=coalesce(?,account_name),account_number=coalesce(?,account_number),branch_name=coalesce(?,branch_name),branch_code=coalesce(?,branch_code),electronic_branch_code=coalesce(?,electronic_branch_code),updated_at=now() where id=?",p.name().trim(),p.contactName().trim(),p.email().trim(),p.phone().trim(),p.address().trim(),p.paymentTerms().trim(),p.deliveryNotes().trim(),p.codNumber()==null?null:p.codNumber().trim(),p.salesPerson()==null?null:p.salesPerson().trim(),p.bankName()==null?null:p.bankName().trim(),p.accountName()==null?null:p.accountName().trim(),p.accountNumber()==null?null:p.accountNumber().trim(),p.branchName()==null?null:p.branchName().trim(),p.branchCode()==null?null:p.branchCode().trim(),p.electronicBranchCode()==null?null:p.electronicBranchCode().trim(),id);return Map.of("saved",true);}
 @GetMapping("/{id}/import-columns") Map<String,String> importColumns(@PathVariable long id){detail(id);try{return json.readValue(db.queryForObject("select import_columns::text from supplier where id=?",String.class,id),new com.fasterxml.jackson.core.type.TypeReference<Map<String,String>>(){});}catch(java.io.IOException e){throw new IllegalStateException(e);}}
 @PutMapping("/{id}/import-columns") Map<String,Object> saveImportColumns(@PathVariable long id,@RequestBody Map<String,String> columns){detail(id);var allowed=Set.of("description","packPrice","sku","quotedPacks","packLabel","unitsPerPack","supplier","reference","quoteDate","validUntil","terms","vatBasis");if(columns.size()>allowed.size()||!allowed.containsAll(columns.keySet())||columns.values().stream().anyMatch(v->v==null||v.length()>100))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose valid column headings up to 100 characters.");try{db.update("update supplier set import_columns=?::jsonb where id=?",json.writeValueAsString(columns),id);}catch(java.io.IOException e){throw new IllegalStateException(e);}return Map.of("saved",true);}
 @GetMapping("/{id}/catalogue") @Transactional(readOnly=true) List<Map<String,Object>> catalogue(@PathVariable long id){detail(id);return db.queryForList("select distinct on(l.supplier_sku) l.*,p.name product_name,b.name brand,p.ordering_unit,q.reference,q.quote_date,q.valid_until,q.id<>(select q2.id from supplier_quote q2 where q2.supplier_id=? order by q2.quote_date desc,q2.id desc limit 1) missing_from_latest from supplier_quote_line l join supplier_quote q on q.id=l.quote_id left join product p on p.id=l.product_id left join brand b on b.id=p.brand_id where q.supplier_id=? order by l.supplier_sku,q.quote_date desc,q.id desc,l.id desc",id,id);}
}
